style.css:
/* Pastel rainbow gradient text */
body p, 
body span, 
body a, 
body h1, 
body h2, 
body h3, 
body h4, 
body h5, 
body h6, 
body li, 
body strong, 
body em,
input[type="text"],
input[type="search"],
textarea {
  background-image: linear-gradient(
    90deg,
    #f8a5c2, /* pastel pink */
    #fbc2eb, /* soft pink-lavender */
    #fdfd96, /* pastel yellow */
    #a8edea, /* soft aqua */
    #a0c4ff, /* pastel blue */
    #bdb2ff, /* lavender */
    #ffc6ff  /* soft lilac-pink */
  );
  background-clip: text;
  -webkit-background-clip: text;
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
}

/* Keep buttons and dropdowns normal */
button, select {
  background: inherit !important;
  color: inherit !important;
  -webkit-text-fill-color: inherit !important;
  -webkit-background-clip: border-box !important;
}

/* Prevent transparent containers from showing rainbow backgrounds */
div, section, header, footer, nav {
  background: inherit !important;
}
